function [jo] = scale_inertia(j, s)
%SCALE_INERTIA  The inertia with each principal moment scaled by s (a campaign's dispersion of the truth body).
%   j: real[1][3][3] (passed a plain number)
%   s: real[1][3] (passed a plain number)
%   returns jo: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    jo = zeros(3, 3);
    jo = j;
    for i = (0):((3) - 1)
        jo((i) + 1, (i) + 1) = (jo((i) + 1, (i) + 1) * s((i) + 1));
    end
end
